## 8. HTTP Interceptors

Interceptors process every HTTP request and response — ideal for authentication headers and error handling:

```typescript
// auth.interceptor.ts
import { Injectable } from "@angular/core";
import {
  HttpRequest,
  HttpHandler,
  HttpEvent,
  HttpInterceptor,
  HttpErrorResponse,
} from "@angular/common/http";
import { Observable, throwError } from "rxjs";
import { catchError } from "rxjs/operators";
import { Router } from "@angular/router";

@Injectable()
export class AuthInterceptor implements HttpInterceptor {
  constructor(private router: Router) {}

  intercept(
    req: HttpRequest<unknown>,
    next: HttpHandler,
  ): Observable<HttpEvent<unknown>> {
    const token = localStorage.getItem("token");

    const authReq = token
      ? req.clone({ setHeaders: { Authorization: `Bearer ${token}` } })
      : req;

    return next.handle(authReq).pipe(
      catchError((error: HttpErrorResponse) => {
        if (error.status === 401) {
          localStorage.removeItem("token");
          this.router.navigate(["/login"]);
        }
        return throwError(() => error);
      }),
    );
  }
}
```

Register in `AppModule`:

```typescript
providers: [
  { provide: HTTP_INTERCEPTORS, useClass: AuthInterceptor, multi: true },
];
```

---

## 9. Reactive Forms

Reactive forms give you full programmatic control over form state and validation:

```typescript
import { Component } from "@angular/core";
import {
  FormBuilder,
  FormGroup,
  Validators,
  AbstractControl,
} from "@angular/forms";

function passwordMatchValidator(control: AbstractControl) {
  const password = control.get("password")?.value;
  const confirm = control.get("confirmPassword")?.value;
  return password === confirm ? null : { mismatch: true };
}

@Component({
  selector: "app-register",
  template: `
    <form [formGroup]="form" (ngSubmit)="onSubmit()">
      <div>
        <input formControlName="email" placeholder="Email" />
        <span *ngIf="email?.invalid && email?.touched">
          {{ email?.hasError("required") ? "Email required" : "Invalid email" }}
        </span>
      </div>
      <div formGroupName="passwords">
        <input
          formControlName="password"
          type="password"
          placeholder="Password"
        />
        <input
          formControlName="confirmPassword"
          type="password"
          placeholder="Confirm"
        />
        <span *ngIf="passwords?.hasError('mismatch') && passwords?.touched">
          Passwords do not match
        </span>
      </div>
      <button type="submit" [disabled]="form.invalid">Register</button>
    </form>
  `,
})
export class RegisterComponent {
  form: FormGroup;

  constructor(private fb: FormBuilder) {
    this.form = this.fb.group({
      email: ["", [Validators.required, Validators.email]],
      passwords: this.fb.group(
        {
          password: ["", [Validators.required, Validators.minLength(8)]],
          confirmPassword: ["", Validators.required],
        },
        { validators: passwordMatchValidator },
      ),
    });
  }

  get email() {
    return this.form.get("email");
  }
  get passwords() {
    return this.form.get("passwords");
  }

  onSubmit(): void {
    if (this.form.valid) {
      console.log(this.form.value);
    }
  }
}
```

